mapper.select:
SELECT p.supplier_id AS supplierId, IFNULL(s.name, '') AS supplierName, SUM(p.total_quantity) AS totalQuantity, SUM(p.total_amount) AS totalAmount, COUNT(1) AS purchaseCount FROM eb_purchase p LEFT JOIN eb_supplier s ON s.id = p.supplier_id WHERE 1 = 1 AND p.status != 3
AND p.create_time >= #{startTime}
AND p.create_time <= #{endTime}
GROUP BY p.supplier_id ORDER BY totalAmount DESC
